const DICTS = Object.freeze({ en: EN, vi: VI });
export function normalizeLanguage(value = 'system') { if (value === 'vi' || value === 'en') return value; const locale = globalThis.navigator?.language?.toLowerCase?.() ?? 'en'; return locale.startsWith('vi') ? 'vi' : 'en'; }
export function t(key, language = 'en', fallback = key) { const lang = normalizeLanguage(language); return DICTS[lang]?.[key] ?? EN[key] ?? fallback; }
export function dictionary(language='en') { return DICTS[normalizeLanguage(language)]; }
